// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

function checkTunnelling(ball, brick) {
  const r = ball.r;
  const b = { x: brick.x - r, y: brick.y - r, w: brick.w + 2 * r, h: brick.h + 2 * r };
  const dx = ball.x - ball.prevX;
  const dy = ball.y - ball.prevY;
  let tmin = -Infinity, tmax = Infinity;
  const p = [-dx, dx, -dy, dy];
  const q = [ball.prevX - b.x, b.x + b.w - ball.prevX, ball.prevY - b.y, b.y + b.h - ball.prevY];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return false;
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > tmax) return false;
        if (t > tmin) tmin = t;
      } else {
        if (t < tmin) return false;
        if (t < tmax) tmax = t;
      }
    }
  }
  return tmax >= 0 && tmin <= 1 && tmax >= tmin;
}

